export function journalView({data,windowChoice,graph,entry,kg,signed,day,escape,arrow,logo,motion,shown}){
 const m=data.metrics,canImport=data.canImport||data.local,source=r=>r.source==='manual'?'Manual entry':'MASS import';
 return `<header class="tr-header"><a class="tr-brand" href="/training" aria-label="My Fitness Analyser training overview">${logo}<span>My Fitness<br><strong>Analyser</strong></span></a><nav aria-label="Main"><a href="/training">Training</a><a href="/journal" aria-current="page">Journal</a><a href="#measurements">Readings</a><a href="/account">Account</a></nav><button class="tr-motion" id="motion" aria-pressed="${motion}" aria-label="Enable motion effects">Motion <span>${motion?'on':'off'}</span></button></header>
 <main id="journal-main" class="jr-main jr-v2"><section class="jr-title"><div><span class="tr-eyebrow"><span class="tr-signal"></span>${data.dataset==='synthetic'?'Synthetic design preview':'Your personal record'}</span><h1>Body journal.</h1><p>Small entries. A longer view.</p></div><a href="#quick-log" class="jr-log-link">${data.canLog?'Log a weigh-in':'Import your history'} ${arrow}</a></section>
 <p id="journal-status" class="jr-save-status" role="status"></p>
 <div class="jr-workspace"><div class="jr-history"><section class="jr-chart-section" aria-label="Weight history"><div class="jr-chart-heading"><h2>Your weight, over time.</h2><div class="tr-window" role="group" aria-label="Journal window">${[['30','30 days'],['90','90 days'],['all','All history']].map(([key,label])=>`<button data-window="${key}" aria-pressed="${windowChoice===key}">${label}</button>`).join('')}</div></div>${graph()}</section>
 <section class="jr-facts" aria-label="Weight summary"><div><span>Latest daily value</span><strong>${kg(m.latestKg)} <small>kg</small></strong><p>${m.latestDate?day(m.latestDate):'Your first reading starts here'}</p></div><div><span>Latest 7-day mean</span><strong>${kg(m.mean7)} <small>kg</small></strong><p>${m.mean7===null?'Needs 3 recorded days in 7 days':m.meanDays+' recorded days · through '+day(m.latestDate)}</p></div><div><span>Change in this window</span><strong>${signed(m.changeKg)} <small>kg</small></strong><p>${m.changeFrom&&m.changeKg!==null?day(m.changeFrom)+' → '+day(m.latestDate):'Two recorded days needed'}</p></div></section></div>
 <aside id="quick-log" class="jr-entry-panel" aria-label="Quick weigh-in">${entry}</aside></div>
 <section id="measurements" class="jr-measurements"><div class="tr-section-head"><div><span class="tr-eyebrow">The readings</span><h2>Every entry, intact.</h2></div><p>${m.recordedDays} days · ${m.weighIns} readings</p></div><div class="jr-entry-list">${data.entries.length?data.entries.slice(0,shown).map(r=>`<article class="jr-entry-row"><button class="jr-date-button" data-date="${r.dateKey}" aria-label="Inspect ${day(r.dateKey)}">${day(r.dateKey)}<span>${source(r)}</span></button><div class="jr-entry-note">${r.note?escape(r.note):'<span>—</span>'}</div><strong>${kg(r.kg)}<small> kg</small></strong>${r.source==='manual'&&data.canLog?`<button class="secondary-button jr-edit" data-edit-weight="${escape(r.entryKey)}" aria-label="Edit ${kg(r.kg)} kg reading on ${day(r.dateKey)}">Edit</button>`:'<span class="jr-source-tag">MASS</span>'}</article>`).join(''):'<div class="jr-empty-small"><h3>No readings in this window.</h3><p>Log a reading or choose All history to see earlier entries.</p></div>'}</div>${data.entries.length>shown?`<button class="secondary-button" id="more-readings">Show more readings (${data.entries.length-shown} remaining)</button>`:''}
 ${data.removed?.length?`<details class="jr-removed"><summary>Removed entries (${data.removed.length})</summary>${data.removed.map(r=>`<div><span>${day(r.dateKey)} · ${kg(r.kg)} kg</span><button class="secondary-button" data-restore-weight="${escape(r.entryKey)}">Restore reading</button></div>`).join('')}</details>`:''}
 <details class="jr-method"><summary>How the chart is calculated</summary><p>${escape(data.method)}</p><p>Daily values average all readings on that date. The original entries and their sources stay separate. Change compares the first and last recorded daily values in the selected window.</p><p>Weight change alone does not establish a change in fitness or body composition. ${data.tombstones} source deletion markers are retained outside the active chart.</p></details></section>
 <section class="jr-import-panel" aria-label="Import and sources"><div><span class="tr-eyebrow">Keep your history</span><h2>Bring MASS with you.</h2><p>Import your backup when you have more to add. Updates stay current, repeated files stay duplicate-free.</p><p class="jr-import-meta">${data.imports.length?'Last imported '+new Date(data.imports[0].importedAt).toLocaleDateString('en-AU'):'No MASS backup imported yet.'}</p></div><div>${canImport?`<button id="choose-file" class="secondary-button">Import MASS backup ${arrow}</button><input type="file" id="mass-file" accept=".json,application/json" hidden>`:'<p>Import is available in your private account or local library.</p>'}${data.cloud||data.local?`<a class="text-button" href="/api/export">Export your complete library ${arrow}</a>`:''}<p id="import-status" role="status"></p><p id="import-error" class="tr-error" role="alert"></p></div></section>
 <section id="strength" class="jr-strength"><div class="tr-section-head"><div><span class="tr-eyebrow">From your MASS history</span><h2>The work around it.</h2></div><p>${m.loggedSessions} logged sessions · ${m.recordedSessionMinutes} recorded min</p></div><div class="jr-strength-list">${data.sessions.length?data.sessions.map(s=>`<article class="jr-strength-row"><div class="jr-session-date"><span>${new Date(s.dateKey+'T12:00Z').getUTCDate()}</span><small>${new Date(s.dateKey+'T12:00Z').toLocaleDateString('en-AU',{month:'short',year:'numeric',timeZone:'UTC'})}</small></div><div><h3>${escape(s.focus)}</h3><span>MASS · ${escape(s.kind)}</span>${s.note?`<details><summary>Session note</summary><p>${escape(s.note)}</p></details>`:''}</div><strong>${s.mins===null?'—':s.mins}<small> min</small></strong></article>`).join(''):'<div class="jr-empty-small"><h3>No imported MASS sessions yet.</h3><p>Your running history is available in Training.</p></div>'}</div><p class="jr-section-note">These are source-recorded focus and duration. Exercise sets, loads and repetitions are not inferred.</p></section>
 <footer class="tr-footer"><span>MY FITNESS ANALYSER</span><p>${escape(data.scope)}</p><a href="/training">Back to training ${arrow}</a></footer></main>
 <dialog id="mass-review" aria-labelledby="review-title"><div class="jr-review-head"><span class="tr-eyebrow">Review before importing</span><button id="close-review" class="icon-button" aria-label="Close import review">×</button></div><div id="review-content"></div></dialog>`;
}
